SELECT arc.id, arc.user_id, u.username, arc.name, arc.description, arc.persona_prompt, arc.is_public, arc.deleted, arc.create_time, arc.update_time, stats.public_count, stats.private_count FROM api_relay_config arc LEFT JOIN sys_user u ON arc.user_id = u.id CROSS JOIN ( SELECT SUM(CASE WHEN is_public = 1 THEN 1 ELSE 0 END) AS public_count, SUM(CASE WHEN is_public = 0 THEN 1 ELSE 0 END) AS private_count FROM api_relay_config WHERE deleted = 0
AND user_id = #{userId}
AND (user_id = #{userId} OR is_public = 1)
AND id = #{id}
AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
) stats WHERE arc.deleted = 0
AND arc.user_id = #{userId}
AND (arc.user_id = #{userId} OR arc.is_public = 1)
AND arc.id = #{id}
AND (arc.name LIKE CONCAT('%', #{keyword}, '%') OR arc.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY arc.create_time DESC
